#include <iostream>
#include <map>
#include <deque>
#include <string>

using namespace std;

using ll = long long;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, ms = 0;
    cin >> n;

    string a;
    cin >> a;

    map<int, int> m;
    for (ll i = 0; i < n; ++i) {
        m[i] = 1;
    }

    for (ll i = 0; i < static_cast<ll>((a.size() + 1) / 2); ++i) {
        ll j = static_cast<ll>(a.size()) - i - 1;

        if (a[i] == a[j] && a[i] != '?') {
            n -= m[a[i] - 'a'];
            m[a[i] - 'a'] = 0;
        } else if (a[i] != a[j] && (a[i] == '?' || a[j] == '?')) {
            if (a[i] == '?')
                a[i] = a[j];
            else
                a[j] = a[i];

            n -= m[a[i] - 'a'];
            m[a[i] - 'a'] = 0;
        } else if (a[i] != a[j]) {
            cout << "IMPOSSIBLE";
            return 0;
        } else {
            ++ms;
        }
    }

    deque<int> va;
    for (const auto& entry : m) {
        if (entry.second == 1) {
            va.push_back(entry.first);
            --ms;
        }
    }

    if (ms < 0) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    while (ms > 0) {
        va.push_front(0);
        --ms;
    }

    for (ll i = 0; i < static_cast<ll>((a.size() + 1) / 2); ++i) {
        ll j = static_cast<ll>(a.size()) - i - 1;

        if (a[i] == '?' && a[j] == '?') {
            if (va.empty()) {
                cout << "IMPOSSIBLE";
                return 0;
            }

            char ch = static_cast<char>(va.front() + 'a');
            a[i] = a[j] = ch;
            va.pop_front();
        }
    }

    if (!va.empty())
        cout << "IMPOSSIBLE";
    else
        cout << a;

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string a;
    cin >> n >> a;

    vector<bool> used(n, false);
    vector<int> unknown;

    int len = static_cast<int>(a.size());

    for (int i = 0; i <= (len - 1) / 2; ++i) {
        int j = len - 1 - i;

        if (a[i] != '?' && a[j] != '?' && a[i] != a[j]) {
            cout << "IMPOSSIBLE";
            return 0;
        }

        if (a[i] == '?' && a[j] != '?') {
            a[i] = a[j];
        } else if (a[i] != '?' && a[j] == '?') {
            a[j] = a[i];
        }

        if (a[i] == '?' && a[j] == '?') {
            unknown.push_back(i);
        } else {
            int letter = a[i] - 'a';
            if (letter >= 0 && letter < n) {
                used[letter] = true;
            }
        }
    }

    vector<int> missing;
    for (int i = 0; i < n; ++i) {
        if (!used[i]) {
            missing.push_back(i);
        }
    }

    if (missing.size() > unknown.size()) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    size_t pos = 0;
    for (int i : unknown) {
        int j = len - 1 - i;
        char ch = pos < missing.size()
                      ? static_cast<char>('a' + missing[pos++])
                      : 'a';
        a[i] = a[j] = ch;
    }

    cout << a;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <deque>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string a;
    cin >> n >> a;

    vector<bool> used(n, false);
    int emptyPairs = 0;
    int len = static_cast<int>(a.size());

    for (int i = 0; i < (len + 1) / 2; ++i) {
        int j = len - i - 1;

        if (a[i] != '?' && a[j] != '?') {
            if (a[i] != a[j]) {
                cout << "IMPOSSIBLE";
                return 0;
            }
        } else if (a[i] == '?' && a[j] != '?') {
            a[i] = a[j];
        } else if (a[i] != '?' && a[j] == '?') {
            a[j] = a[i];
        } else {
            ++emptyPairs;
            continue;
        }

        int letter = a[i] - 'a';
        if (letter >= 0 && letter < n)
            used[letter] = true;
    }

    deque<int> letters;
    for (int i = 0; i < n; ++i) {
        if (!used[i])
            letters.push_back(i);
    }

    if (static_cast<int>(letters.size()) > emptyPairs) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    while (static_cast<int>(letters.size()) < emptyPairs)
        letters.push_front(0);

    for (int i = 0; i < (len + 1) / 2; ++i) {
        int j = len - i - 1;
        if (a[i] == '?') {
            char ch = static_cast<char>('a' + letters.front());
            letters.pop_front();
            a[i] = a[j] = ch;
        }
    }

    cout << a;
    return 0;
}

